mapper.select:
SELECT o.id AS orderId, o.order_no AS orderNo, si.title AS showTitle, ss.session_time AS sessionTime, o.pay_amount AS payAmount, o.status AS status, o.expire_time AS expireTime, o.create_time AS createTime FROM orders o LEFT JOIN show_info si ON si.id = o.show_id LEFT JOIN show_session ss ON ss.id = o.session_id WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.id DESC
